import{_ as o,o as a,c as e,a2 as d}from"./chunks/framework.Bqa2y7hU.js";const Q=JSON.parse('{"title":"接入方式总览","description":"Xiaoyi_QQ_V4 的两种机器人适配器（QQ 官方、QQ OneBot 11）对比与选择建议。","frontmatter":{"title":"接入方式总览","description":"Xiaoyi_QQ_V4 的两种机器人适配器（QQ 官方、QQ OneBot 11）对比与选择建议。"},"headers":[],"relativePath":"platforms/overview.md","filePath":"platforms/overview.md","lastUpdated":1789447883000}'),l={name:"platforms/overview.md"};function r(i,t,c,n,s,h){return a(),e("div",null,[...t[0]||(t[0]=[d('<h1 id="接入方式总览-🌐" tabindex="-1">接入方式总览 🌐 <a class="header-anchor" href="#接入方式总览-🌐" aria-label="Permalink to &quot;接入方式总览 🌐&quot;">​</a></h1><p>Xiaoyi_QQ_V4 目前提供两种适配器（adapter）：直接对接 <strong>QQ 官方开放平台</strong>，或通过 <strong>OneBot 11</strong> 接入第三方 QQ 实现端。这页把两者的连接方式、能力边界和部署成本摆在一起，帮你决定走哪条路。</p><p>换适配器意味着换一套平台侧配置、有时还意味着换一个 QQ 号，所以在动手之前建议先看完这页。</p><h2 id="_1-一张表看清两种适配器" tabindex="-1">1. 一张表看清两种适配器 <a class="header-anchor" href="#_1-一张表看清两种适配器" aria-label="Permalink to &quot;1. 一张表看清两种适配器&quot;">​</a></h2><table tabindex="0"><thead><tr><th>对比项</th><th><code>qq_official</code>（QQ 官方）</th><th><code>qq_onebot</code>（OneBot 11）</th></tr></thead><tbody><tr><td>机器人身份</td><td>QQ 开放平台上注册的官方机器人</td><td>你自己登录的 QQ 号</td></tr><tr><td>支持的连接方式</td><td>Webhook 回调、WebSocket 网关</td><td>仅反向 WebSocket</td></tr><tr><td>需要公网域名吗</td><td>Webhook 模式需要；WebSocket 网关模式不需要</td><td>不需要，但要保证实现端能连到框架</td></tr><tr><td>按钮 / Markdown 消息</td><td>支持</td><td>不渲染按钮与富文本，需改走纯文本</td></tr><tr><td>禁言 / 踢人等群管理</td><td>支持，但不少接口需要平台单独开权限</td><td>走 OneBot 标准接口，同样可用</td></tr><tr><td>入群审批</td><td>支持（QQ 官方专属能力）</td><td>不可用</td></tr><tr><td>你要额外部署什么</td><td>无，只需在 QQ 开放平台注册配置</td><td>自己部署一个实现端（NapCat / Lagrange / go-cqhttp 等）</td></tr><tr><td>适配器标识</td><td><code>qq_official</code></td><td><code>qq_onebot</code></td></tr></tbody></table><h2 id="_2-选哪一个" tabindex="-1">2. 选哪一个 <a class="header-anchor" href="#_2-选哪一个" aria-label="Permalink to &quot;2. 选哪一个&quot;">​</a></h2><p><strong>选 QQ 官方，如果你：</strong></p><ul><li>希望走平台官方渠道，机器人是「官方机器人」身份</li><li>需要按钮、Markdown 这类富文本交互</li><li>需要入群审批这类 QQ 官方专属能力</li><li>不想额外维护一个常驻的实现端进程</li></ul><p>代价是：很多群管理接口默认不开，需要你去 QQ 开放平台为机器人申请对应权限；群内要免 @ 收到全量消息，也需要单独授权。</p><p><strong>选 OneBot 11，如果你：</strong></p><ul><li>需要的能力主要落在群管理上（禁言、踢人、撤回等）</li><li>手头已经有一台跑着 NapCat / Lagrange / go-cqhttp 的机器</li><li>不介意自己部署、登录并长期维护实现端</li></ul><p>代价是：富文本能力会打折，按钮和 Markdown 发出去会变成纯文本；入群审批这类官方专属能力用不了。</p><div class="tip custom-block"><p class="custom-block-title">两者可以并存</p><p>一个 Xiaoyi_QQ_V4 实例可以同时接入多个机器人，官方机器人和 OneBot 机器人可以共存，各自独立配置插件。具体数量上限由你的套餐决定，见 <a href="/RuaBot.Doc/console/billing">订阅 · 卡密 · 充值</a>。</p></div><h2 id="_3-连接方式怎么选" tabindex="-1">3. 连接方式怎么选 <a class="header-anchor" href="#_3-连接方式怎么选" aria-label="Permalink to &quot;3. 连接方式怎么选&quot;">​</a></h2><p><code>qq_official</code> 有两种连接方式，区别只在于「谁来发起连接」：</p><table tabindex="0"><thead><tr><th>连接方式</th><th>谁主动</th><th>要不要公网域名</th><th>适合场景</th></tr></thead><tbody><tr><td>WebSocket 网关（推荐）</td><td>框架主动连平台</td><td>不需要</td><td>绝大多数情况，尤其是没有公网域名的服务器</td></tr><tr><td>Webhook 回调</td><td>平台回调你的服务</td><td>需要</td><td>已经有稳定公网域名、希望回调直连的场景</td></tr></tbody></table><p><code>qq_onebot</code> 只有一种连接方式：<strong>反向 WebSocket（reverse WebSocket）</strong>——实现端主动连到框架，框架不需要对外暴露任何地址。</p><p>三条具体路径：</p><ul><li><a href="/RuaBot.Doc/platforms/qq-official">QQ 官方：WebSocket 网关</a>（推荐，最省事）</li><li><a href="/RuaBot.Doc/platforms/qq-official-webhook">QQ 官方：Webhook 回调</a></li><li><a href="/RuaBot.Doc/platforms/qq-onebot">QQ OneBot 11</a></li></ul><h2 id="_4-创建机器人的两条路径" tabindex="-1">4. 创建机器人的两条路径 <a class="header-anchor" href="#_4-创建机器人的两条路径" aria-label="Permalink to &quot;4. 创建机器人的两条路径&quot;">​</a></h2><p>不管选哪种适配器，最后都要回到控制台的「我的机器人」页面把机器人加进去。区别在于<strong>前置准备在哪做</strong>：</p><p><strong>路径 A：QQ 官方</strong></p><ol><li>先去 QQ 开放平台创建机器人应用，拿到 <code>AppID</code> 与 <code>AppSecret</code></li><li>在 QQ 开放平台为机器人配置需要的权限</li><li>回到控制台 <a href="/RuaBot.Doc/console/bots">我的机器人</a>，点「添加机器人」，平台选 <code>qq_official</code></li></ol><p><strong>路径 B：OneBot 11</strong></p><ol><li>先在你自己的机器上部署实现端（NapCat / Lagrange / go-cqhttp）并登录 QQ</li><li>回到控制台 <a href="/RuaBot.Doc/console/bots">我的机器人</a>，点「添加机器人」，平台选 <code>qq_onebot</code></li><li>控制台会给出一个反向 WS 地址，把它填回实现端</li></ol><p>两条路径在控制台里是同一个「两步向导」，第二步的内容会随你选的平台变化。</p><details class="details custom-block"><summary>截图占位</summary><p>截「添加机器人」向导第一步的平台选择页，重点露出 <code>qq_official</code> 与 <code>qq_onebot</code> 两个可选项及其说明文案。后续每页的截图占位同理，只为以后补图留位置，不影响现在阅读。</p></details><h2 id="_5-通用前置检查" tabindex="-1">5. 通用前置检查 <a class="header-anchor" href="#_5-通用前置检查" aria-label="Permalink to &quot;5. 通用前置检查&quot;">​</a></h2><p>不管走哪条路，动手前先确认这几件事：</p><ul><li>服务已经在运行，并且你能登录控制台（见 <a href="/RuaBot.Doc/deploy/install">安装</a>）</li><li>你手上有一个可用的 QQ 号或已注册的官方机器人</li><li>机器人的数量没有超出套餐额度（套餐决定你能建几个机器人，见 <a href="/RuaBot.Doc/console/billing">订阅 · 卡密 · 充值</a>）</li></ul><h2 id="下一步" tabindex="-1">下一步 <a class="header-anchor" href="#下一步" aria-label="Permalink to &quot;下一步&quot;">​</a></h2><ul><li><a href="/RuaBot.Doc/platforms/qq-official">QQ 官方：WebSocket 网关</a></li><li><a href="/RuaBot.Doc/platforms/qq-onebot">QQ OneBot 11</a></li><li><a href="/RuaBot.Doc/console/bots">我的机器人</a></li></ul>',32)])])}const b=o(l,[["render",r]]);export{Q as __pageData,b as default};
